<h2>Calculate lead-to-customer conversion</h2><p class="lead">Measure how many leads become customers and estimate leads needed for a target customer count.</p><div class="notice">Salesforce describes conversion rate as conversions divided by total visitors or leads. Cohort timing and lead definitions determine whether the metric is meaningful.</div><div class="form-grid"><div class="field"><label for="leads">Leads in cohort / period</label><input id="leads" type="number" value="1000" min="0" step="1"></div><div class="field"><label for="customers">Customers acquired</label><input id="customers" type="number" value="50" min="0" step="1"></div><div class="field"><label for="target">Target customers</label><input id="target" type="number" value="80" min="0" step="1"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Lead-to-customer conversion</span><strong id="rate">—</strong></div><div class="metric"><span>Non-converted leads</span><strong id="lost">—</strong></div><div class="metric"><span>Leads needed at current rate</span><strong id="needed">—</strong></div><div class="metric"><span>Customers from +1 percentage point</span><strong id="lift">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('rate').textContent='—';$('lost').textContent='—';$('needed').textContent='—';$('lift').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const l=num('leads'),c=num('customers'),t=num('target');if(!(l>=0&&c>=0&&c<=l&&t>=0))throw 0;const r=l>0?c/l:NaN;$('rate').textContent=Number.isFinite(r)?fmt(r*100,2)+'%':'—';$('lost').textContent=fmt(l-c,0);$('needed').textContent=r>0?fmt(Math.ceil(t/r),0):'Unavailable';$('lift').textContent=fmt(l*0.01,1);$('note').textContent='Keep numerator and denominator in the same cohort definition. Comparing customers acquired this month with leads created this month can be misleading when sales cycles cross periods.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
